import sys


def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])

    soma = 0
    dias = 0
    for i in range(1, n + 1):
        soma += int(input_data[i])
        if soma >= 1000000:
            dias = i
            break

    print(dias)


if __name__ == "__main__":
    main()
